//go:build windows

package main

import "encoding/base64"

const trayIconBase64 = ""

var trayIconData = mustDecodeTrayIcon()

func mustDecodeTrayIcon() []byte {
	data, err := base64.StdEncoding.DecodeString(trayIconBase64)
	if err != nil {
		panic("invalid embedded Windows tray icon: " + err.Error())
	}
	return data
}
